arguments.command:
cd /tmp/sv-c966a15bc74b44f581636134da0704e7/symbols && \
# Use dynamic symbols to resolve addresses
# Frames: #01=0x222098, #02=0x222234, #03=0x19bac0, #06=0x19bc14
for addr in 0x222098 0x222234 0x19bac0 0x19bc14; do
  echo -n "pc $addr -> "
  # Find the closest symbol <= address
  readelf --dyn-syms libmonosgen-2.0.so 2>/dev/null | awk -v addr="$addr" '
    BEGIN { target = strtonum(addr); best_name = "??"; best_addr = 0; best_size = 0 }
    /FUNC/ {
      sym_addr = strtonum("0x" $2);
      sym_size = strtonum($3);
      if (sym_addr <= target && sym_addr > best_addr) {
        best_addr = sym_addr;
        best_name = $NF;
        best_size = sym_size;
      }
    }
    END {
      offset = target - best_addr;
      printf "%s+0x%x", best_name, offset;
      if (best_size > 0 && offset >= best_size) printf " (outside bounds)";
      printf "\n";
    }
  '
done

