# Get all function symbols sorted by address, find containing symbol for each PC
readelf --dyn-syms libmonosgen-2.0.so 2>/dev/null | awk '/FUNC/ && $3+0 > 0 { printf "0x%s %s %s\n", $2, $3, $NF }' | sort > /tmp/mono_syms.txt
for addr in 0x222098 0x222234 0x19bac0 0x19bc14; do
  target=$(printf "%d" $addr)
  echo -n "pc $addr -> "
  awk -v target="$target" '{
    sym_addr = strtonum($1); sym_size = strtonum($2); name = $3
    if (sym_addr <= target && (sym_addr + sym_size) > target) {
      printf "%s+0x%x\n", name, target - sym_addr
      found = 1; exit
    }
  } END { if (!found) print "??" }' /tmp/mono_syms.txt
done", "description": "Find containing symbol for each address"}
